 void chooseRole(final Bitmap copied,final String text){final boolean[] used={false};AlertDialog dialog=new AlertDialog.Builder(a).setTitle("어디에 추가할까요?").setItems(new String[]{"문제 · 새 암기노트","지문 · 현재 노트에 추가","풀이 · 현재 노트에 추가"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int role){if(role!=0&&findNote(doc.optString("current"))==null){message("먼저 ‘문제’로 새 노트를 만들어 주세요.");return;}used[0]=true;Bitmap crop=copied!=null?copied:text!=null?null:canvas.cropSelection();if(crop==null&&text==null){message("선택 영역을 확인해 주세요.");return;}previewContent(role,crop,text);}}).create();dialog.setOnDismissListener(new DialogInterface.OnDismissListener(){public void onDismiss(DialogInterface d){if(!used[0]&&copied!=null)copied.recycle();}});dialog.show();}
 void clipboardCapture(){android.content.ClipboardManager cm=(android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE);ClipData clip=cm==null?null:cm.getPrimaryClip();if(clip==null||clip.getItemCount()==0){message("AI 셀렉트에서 복사하거나, 선택 도구로 PDF 영역을 지정해 주세요.");setMode(1);return;}ClipData.Item item=clip.getItemAt(0);final Uri uri=item.getUri();if(uri!=null){a.startBusy("복사한 그림을 가져오는 중…");worker.execute(new Runnable(){public void run(){try{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=a.getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,o);}if(o.outWidth<=0||o.outHeight<=0)throw new IOException("복사한 그림을 읽을 수 없습니다. AI 셀렉트에서 다시 복사해 주세요.");int sample=1;while((long)(o.outWidth/sample)*(o.outHeight/sample)>3000000L)sample*=2;o.inJustDecodeBounds=false;o.inSampleSize=sample;final Bitmap image;try(InputStream in=a.getContentResolver().openInputStream(uri)){image=BitmapFactory.decodeStream(in,null,o);}if(image==null)throw new IOException("그림 읽기 실패");a.runOnUiThread(new Runnable(){public void run(){a.endBusy();if(destroyed){image.recycle();return;}chooseRole(image,null);}});}catch(final Exception e){a.runOnUiThread(new Runnable(){public void run(){a.endBusy();a.error(e);}});}}});return;}CharSequence t=item.getText();if(t==null||t.toString().trim().isEmpty()){message("AI 셀렉트에서 그림 또는 글자를 복사해 주세요.");return;}chooseRole(null,t.toString());}
 void previewContent(final int role,final Bitmap crop,final String text){LinearLayout box=a.u.col();final ImageView image=new ImageView(a);if(crop!=null){image.setImageBitmap(crop);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);box.addView(image,new LinearLayout.LayoutParams(-1,a.u.dp(230)));}else{ScrollView scroll=new ScrollView(a);TextView content=a.u.text(text,16,a.u.ink);scroll.addView(content);box.addView(scroll,new LinearLayout.LayoutParams(-1,a.u.dp(230)));}final EditText title=new EditText(a);if(role==0){title.setHint("문제 제목");title.setText(text==null?"문제 "+(notes().length()+1)+" · "+(page+1)+"쪽":text.split("\\n",2)[0]);box.addView(title);}final boolean[] saving={false};AlertDialog dialog=new AlertDialog.Builder(a).setTitle(PdfClipRules.label(role)+" 추가 미리보기").setView(box).setNegativeButton("취소",null).setPositiveButton("추가",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){saving[0]=true;if(crop!=null)saveCrop(role,title.getText().toString().trim(),crop);else commitText(role,title.getText().toString().trim(),text);}}).create();dialog.setOnDismissListener(new DialogInterface.OnDismissListener(){public void onDismiss(DialogInterface d){image.setImageDrawable(null);if(!saving[0]&&crop!=null)crop.recycle();}});dialog.show();}
 void commitText(int role,String title,String text){Note old=role==0?null:findNote(doc.optString("current"));JSONObject snapshot=null;Note target=null;boolean saved=false;try{snapshot=new JSONObject(state.toString());String subj=doc.optString("subject",subject);if(subj.isEmpty()){Iterator<String> ids=a.db.groups("subjects",null).keySet().iterator();if(!ids.hasNext())throw new IOException("과목을 먼저 추가해 주세요.");subj=ids.next();}target=PdfCaptureNotes.prepareText(old,role,title,subj,doc.optString("chapter",chapter),text);a.db.save(target);saved=true;JSONObject record=notes().optJSONObject(target.id);if(record==null){record=new JSONObject().put("doc",doc.optString("id")).put("clips",new JSONArray());notes().put(target.id,record);}record.getJSONArray("clips").put(new JSONObject().put("file","").put("text",text).put("role",role).put("page",page).put("doc",doc.optString("id")));doc.put("current",target.id);persist();refreshCurrent();message("추가 완료 · "+target.title+" · 아래 저장으로 확인");}catch(Exception e){if(saved)try{if(old==null)a.db.delete(target);else a.db.save(old);}catch(Exception rollback){e.addSuppressed(rollback);}if(snapshot!=null){String id=doc.optString("id");state=snapshot;doc=findDoc(id);}a.error(e);}}
 void saveCrop(final int role,final String title,final Bitmap crop){if(role==0&&title.isEmpty()){crop.recycle();message("문제 제목을 입력해 주세요.");return;}final Note existing=role==0?null:findNote(doc.optString("current"));if(role!=0&&existing==null){crop.recycle();message("추가할 노트를 찾을 수 없습니다.");return;}final String file=UUID.randomUUID()+".img";final int sourcePage=page;final String docId=doc.optString("id");add.setEnabled(false);a.startBusy("암기노트에 추가하는 중…");worker.execute(new Runnable(){public void run(){final File image=new File(new File(a.getFilesDir(),"images"),file);File temp=new File(image.getParentFile(),file+".part");try{image.getParentFile().mkdirs();try(OutputStream out=new FileOutputStream(temp)){if(!crop.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("그림 저장 실패");}if(!temp.renameTo(image))throw new IOException("그림 저장 실패");crop.recycle();a.runOnUiThread(new Runnable(){public void run(){if(destroyed){image.delete();return;}a.endBusy();add.setEnabled(true);commitCrop(role,title,existing,file,docId,sourcePage,image);}});}catch(final Exception e){crop.recycle();temp.delete();image.delete();a.runOnUiThread(new Runnable(){public void run(){a.endBusy();add.setEnabled(true);a.error(e);}});}}});}
 void commitCrop(int role,String title,Note old,String file,String docId,int sourcePage,File image){JSONObject snapshot=null;Note target=null;boolean saved=false;try{snapshot=new JSONObject(state.toString());String targetSubject=doc.optString("subject",subject);if(role==0&&targetSubject.isEmpty()){Iterator<String> ids=a.db.groups("subjects",null).keySet().iterator();if(!ids.hasNext())throw new IOException("과목을 먼저 추가해 주세요.");targetSubject=ids.next();}
   target=PdfCaptureNotes.prepare(old,role,title,targetSubject,doc.optString("chapter",chapter),file);a.db.save(target);saved=true;
   JSONObject record=notes().optJSONObject(target.id);if(record==null){record=new JSONObject().put("doc",docId).put("clips",new JSONArray());notes().put(target.id,record);}record.getJSONArray("clips").put(new JSONObject().put("file",file).put("role",role).put("page",sourcePage).put("doc",docId));doc.put("current",target.id);state.put("lastNote",target.id);persist();canvas.clearSelection();refreshCurrent();message("추가 완료 · "+target.title+" · 아래 저장으로 확인");
  }catch(Exception e){boolean rolledBack=!saved;if(saved)try{if(old==null)a.db.delete(target);else a.db.save(old);rolledBack=true;}catch(Exception rollback){e.addSuppressed(rollback);}if(snapshot!=null){state=snapshot;doc=findDoc(docId);}if(rolledBack)image.delete();a.error(e);}}
 JSONObject findDoc(String id){JSONArray list=docs();for(int i=0;i<list.length();i++)if(id.equals(list.optJSONObject(i).optString("id")))return list.optJSONObject(i);return null;}
 void currentMenu(){final Note n=findNote(doc.optString("current"));if(n==null){selectCurrent();return;}new AlertDialog.Builder(a).setTitle(n.title).setItems(new String[]{"현재 노트 보기/수정","다른 노트에 이어 추가","방금 추가 취소","방금 추가 위치 변경","해당 PDF 원본으로"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){if(i==0){if(!remember())return;ticket++;if(search!=null)search.dispose();screen=null;canvas.dispose();worker.shutdown();a.detail(n);}if(i==1)selectCurrent();if(i==2)undoLast(false,-1);if(i==3)new AlertDialog.Builder(a).setTitle("방금 추가한 영역의 위치").setItems(new String[]{"문제","지문","풀이"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int role){undoLast(true,role);}}).show();if(i==4)openSource(n.id);}}).show();}
 void selectCurrent(){final ArrayList<Note> list=a.db.query("");ArrayList<String> titles=new ArrayList<String>();final ArrayList<Note> eligible=new ArrayList<Note>();for(Note n:list)if(notes().has(n.id)){eligible.add(n);titles.add(n.title);}if(eligible.isEmpty()){message("PDF에서 ‘문제’를 추가하면 새 노트가 만들어집니다.");return;}new AlertDialog.Builder(a).setTitle("이어서 추가할 노트").setItems(titles.toArray(new String[0]),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){try{doc.put("current",eligible.get(i).id);persist();refreshCurrent();}catch(Exception e){a.error(e);}}}).show();}
 void undoLast(boolean move,int role){Note original=findNote(doc.optString("current"));if(original==null)return;JSONObject record=notes().optJSONObject(original.id);JSONArray clips=record==null?null:record.optJSONArray("clips");if(clips==null||clips.length()==0){message("추가 기록이 없습니다.");return;}JSONObject snapshot=null;try{snapshot=new JSONObject(state.toString());JSONObject clip=clips.getJSONObject(clips.length()-1);String file=clip.getString("file");int before=clip.getInt("role");Note n=Note.from(new JSONObject(original.json().toString()));String marker=clip.has("text")?(before==2?PdfClipRules.solutionText(clip.getString("text")):clip.getString("text")):InlineImageText.marker(file);if(move)n.body=clip.has("text")?PdfClipRules.moveText(n.body,before,role,clip.getString("text")):PdfClipRules.move(n.body,before,role,marker);else n.body=PdfClipRules.undo(n.body,before,marker);
  for(int i=n.images.length()-1;i>=0;i--){JSONObject im=n.images.optJSONObject(i);if(file.equals(im.optString("file"))){if(move){JSONArray masks=new JSONArray();if(role==2)masks.put(new JSONArray().put(0).put(0).put(1).put(1));im.put("masks",masks);}else n.images.remove(i);}}
  if(move)clip.put("role",role);else clips.remove(clips.length()-1);a.db.save(n);try{persist();}catch(Exception e){a.db.save(original);throw e;}refreshCurrent();message(move?"위치를 변경했습니다.":"방금 추가를 취소했습니다.");
 }catch(Exception e){if(snapshot!=null){state=snapshot;doc=findDoc(doc.optString("id"));}a.error(e);}}
 void openSource(String noteId){JSONObject record=notes().optJSONObject(noteId);JSONArray clips=record==null?null:record.optJSONArray("clips");if(clips==null||clips.length()==0){message("원본 위치가 없습니다.");return;}JSONObject clip=null,source=null;for(int i=clips.length()-1;i>=0;i--){JSONObject c=clips.optJSONObject(i),candidate=findDoc(c.optString("doc"));if(candidate!=null){clip=c;source=candidate;break;}}if(source==null){message("원본 PDF를 찾을 수 없습니다.");return;}if(screen==a.root&&!remember())return;open(source,clip.optInt("page"));}
 void updatePageLabel(){if(pageLabel==null||doc==null)return;String label="현재 "+(page+1)+"쪽 / 전체 "+count+"쪽";if(doc.has("bookOffset")){int book=PdfDocumentRules.bookPage(doc,page);label+=book>0?" · 책 "+book+"쪽":" · 책 앞부분";}pageLabel.setText(label);}
 void options(){new AlertDialog.Builder(a).setTitle("PDF 공부").setItems(new String[]{"책갈피 추가·목록","이 PDF의 암기노트 모아보기","책 쪽수 맞추기","문서 관리 · 이름·용량·삭제","전체 백업 · PDF·필기·노트","필기 전체 지우기 · 현재 PDF 페이지","현재 노트 선택"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int i){if(i==0)PdfLibrary.bookmarks(PdfStudy.this,doc);if(i==1)PdfLibrary.notes(PdfStudy.this,doc);if(i==2)PdfLibrary.match(PdfStudy.this,doc);if(i==3)PdfLibrary.manage(PdfStudy.this,doc);if(i==4)PdfLibrary.backupMenu(PdfStudy.this);if(i==5)a.u.confirm("PDF 페이지 필기 지우기","이 페이지의 필기를 지울까요?",new Runnable(){public void run(){canvas.clearInk();}});if(i==6)selectCurrent();}}).show();}
